import re
import time
from rdflib import Graph
from api_utils import send_prompt, extract_between_markers

def sanitize_turtle_text(turtle_text: str) -> str:
    """Remove non-RDF noise and malformed fragments like ?A :connectedTo ?B ."""
    cleaned_lines = []
    for line in turtle_text.splitlines():
        line = line.strip()
        if not line:
            continue

        # Skip markers, code blocks, or autogenerated comments
        if any(x in line for x in ["###", "```", ":end_turtle", "Turtle block"]):
            continue

        # 🧹 Remove illegal SPARQL-style variable triples
        if re.search(r"\?[A-Za-z]", line):
            print(f"🪓 Removed SPARQL-like triple: {line}")
            continue

        cleaned_lines.append(line)

    return "\n".join(cleaned_lines)


def clean_prefixes_and_headers(turtle_text: str) -> str:
    """Remove duplicate prefixes and ontology headers."""
    seen_prefixes = set()
    cleaned_lines = []
    for line in turtle_text.splitlines():
        prefix_match = re.match(r'@prefix\s+(\S+):', line)
        if prefix_match:
            prefix = prefix_match.group(1)
            if prefix in seen_prefixes:
                continue
            seen_prefixes.add(prefix)
        if re.search(r'(rdf:type\s+owl:Ontology)', line) and any('Ontology' in l for l in cleaned_lines[-5:]):
            continue
        cleaned_lines.append(line)
    return "\n".join(cleaned_lines)


def llm_fix_turtle_block(problem_block: str, error_message: str) -> str:
    """Ask LLM to fix malformed Turtle syntax."""
    prompt = f"""
You are an expert in RDF and Turtle syntax repair. The following Turtle fragment failed to parse.

Error:
{error_message}

Problematic code:
{problem_block}

Please fix the syntax while preserving its intended semantics.
If you encounter variable-like nodes (?A, ?B, etc.), replace them with proper blank nodes or example IRIs.
Return ONLY valid Turtle triples between the markers.

###start_turtle###
###end_turtle###
"""
    reply = send_prompt(prompt, persona="RDF/Turtle syntax expert", step_name="turtle_repair")
    fixed = extract_between_markers(reply, "###start_turtle###", "###end_turtle###")
    if fixed and fixed[0].strip():
        print("🤖 LLM proposed fix for malformed Turtle.")
        return fixed[0].strip()
    print("⚠️ LLM returned no fix, keeping original block.")
    return problem_block


def find_problematic_block(text: str, error_message: str) -> str:
    match = re.search(r"at line (\d+)", error_message)
    if not match:
        return ""
    line_no = int(match.group(1))
    lines = text.splitlines()
    start = max(0, line_no - 3)
    end = min(len(lines), line_no + 3)
    return "\n".join(lines[start:end])


def deduplicate_triples(turtle_text: str, max_retries: int = 20) -> str:
    """Try parsing ontology; if it fails, use LLM to fix the bad block."""
    g = Graph()
    working_text = turtle_text

    for attempt in range(1, max_retries + 1):
        try:
            g.parse(data=working_text, format="turtle")
            print(f"✅ Parse succeeded on attempt {attempt}.")
            return g.serialize(format="turtle")
        except Exception as e:
            print(f"⚠️ Parse failed (attempt {attempt}): {e}")
            block = find_problematic_block(working_text, str(e))
            if not block.strip():
                print("⚠️ Could not isolate problematic section; aborting repair.")
                break
            fixed_block = llm_fix_turtle_block(block, str(e))
            working_text = working_text.replace(block, fixed_block)
            time.sleep(2)

    print("❌ Could not fully repair ontology after multiple attempts.")
    return working_text


def merge_entities(turtle_text: str) -> str:
    """Merge repeated subject definitions, but skip if parse fails."""
    g = Graph()
    try:
        g.parse(data=turtle_text, format="turtle")
    except Exception as e:
        print("⚠️ Skipping merge_entities — graph still not fully valid:", e)
        return turtle_text

    merged = Graph()
    for subj in set(g.subjects()):
        for pred, obj in set(g.predicate_objects(subj)):
            merged.add((subj, pred, obj))
    return merged.serialize(format="turtle")


def preprocess_turtle(ontology_text: str) -> str:
    """Full cleaning + LLM-assisted repair pipeline."""
    cleaned = sanitize_turtle_text(ontology_text)
    cleaned = clean_prefixes_and_headers(cleaned)
    cleaned = deduplicate_triples(cleaned)
    cleaned = merge_entities(cleaned)
    return cleaned


def clean_ontology_file(input_path: str, output_path: str):
    print(f"📂 Loading ontology from {input_path}...")
    with open(input_path, "r", encoding="utf-8") as f:
        ontology_text = f.read()

    print("🧹 Cleaning ontology (LLM-assisted)...")
    cleaned_text = preprocess_turtle(ontology_text)

    with open(output_path, "w", encoding="utf-8") as f:
        f.write(cleaned_text)

    print(f"✅ Cleaned ontology saved to {output_path}")


def clean_ontology_text(turtle_text: str) -> str:
    """Importable entry point: clean Turtle text and return cleaned Turtle text."""
    return preprocess_turtle(turtle_text)


if __name__ == "__main__":
    import sys
    if len(sys.argv) == 3:
        clean_ontology_file(sys.argv[1], sys.argv[2])
    else:
        print("Usage: python validate_fix_ontology_syntax.py <input.ttl> <output.ttl>")

# ---------------------------------------------------------------------------
# Format-agnostic file entry point used by the Gradio app
# ---------------------------------------------------------------------------
def _candidate_formats(path: str):
    from pathlib import Path
    from rdflib.util import guess_format
    candidates = []
    guessed = guess_format(path)
    if guessed:
        candidates.append(guessed)
    try:
        head = Path(path).read_bytes()[:4096].lstrip().lower()
        if head.startswith(b"<?xml") or b"<rdf:rdf" in head:
            candidates.insert(0, "xml")
        elif head.startswith((b"@prefix", b"prefix", b"base")):
            candidates.insert(0, "turtle")
        elif head.startswith((b"{", b"[")):
            candidates.insert(0, "json-ld")
    except OSError:
        pass
    for fmt in ("xml", "turtle", "json-ld", "nt", "n3", "trig", "trix"):
        if fmt not in candidates:
            candidates.append(fmt)
    return candidates


def load_or_repair_ontology(path: str, *, allow_llm: bool = True, max_chars: int = 180_000):
    """Load any common RDF serialization and return ``(Graph, format, note)``.

    When all parsers fail and an API key is configured, the model is asked to
    convert/fix the source into valid Turtle. The repaired Turtle is parsed
    before it is returned; an unparseable model response is never accepted.
    """
    from pathlib import Path
    import api_utils

    errors = []
    for fmt in _candidate_formats(path):
        graph = Graph()
        try:
            graph.parse(path, format=fmt)
            return graph, fmt, "parsed"
        except Exception as exc:  # noqa: BLE001
            errors.append(f"{fmt}: {exc}")

    if not allow_llm:
        raise RuntimeError("Could not parse ontology: " + " | ".join(errors))

    text = Path(path).read_text(encoding="utf-8", errors="replace")
    if len(text) > max_chars:
        raise RuntimeError(
            "The ontology is malformed and too large for whole-file syntax repair. "
            "Please validate/convert it with an RDF editor first. Parse errors: "
            + " | ".join(errors[:3])
        )

    prompt = f"""You are an RDF/OWL syntax repair expert.
The source below could not be parsed in any common RDF serialization.
Convert it to syntactically valid Turtle while preserving every recoverable
ontology assertion and IRI.

Strict rules:
- Do not invent ontology entities or example placeholders.
- Preserve labels, comments, provenance, alignments, restrictions and metadata.
- Repair syntax only; do not redesign ontology semantics.
- Return only Turtle between the markers.

Parser errors:
{chr(10).join(errors[:6])}

Source:
{text}

###start_turtle###
###end_turtle###
"""
    raw = api_utils.send_prompt_raw(
        prompt, persona="RDF and OWL syntax repair expert", step_name="ontology_file_syntax_repair"
    )
    blocks = extract_between_markers(raw, "###start_turtle###", "###end_turtle###")
    if not blocks:
        raise RuntimeError("The syntax-repair model did not return a Turtle block.")
    repaired = blocks[0].strip()
    graph = Graph()
    try:
        graph.parse(data=repaired, format="turtle")
    except Exception as exc:
        raise RuntimeError(f"The syntax-repair model returned invalid Turtle: {exc}") from exc
    return graph, "turtle", "llm_repaired"
